// A docx is a ZIP. Let's use Node to read it:
const buf = fs.readFileSync('/workspace/testbed/docs/customer_report.docx');

// Minimal ZIP parser to find word/document.xml
function findLocalFile(buf, name) {
  let offset = 0;
  while (offset < buf.length - 4) {
    if (buf.readUInt32LE(offset) === 0x04034b50) { // local file header
      const compMethod = buf.readUInt16LE(offset + 8);
      const compSize = buf.readUInt32LE(offset + 18);
      const uncompSize = buf.readUInt32LE(offset + 22);
      const nameLen = buf.readUInt16LE(offset + 26);
      const extraLen = buf.readUInt16LE(offset + 28);
      const fileName = buf.slice(offset + 30, offset + 30 + nameLen).toString('utf8');
      const dataStart = offset + 30 + nameLen + extraLen;
      const data = buf.slice(dataStart, dataStart + compSize);
      if (fileName === name) {
        if (compMethod === 8) { // deflate
          return zlib.inflateRawSync(data).toString('utf8');
        }
        return data.toString('utf8');
      }
      offset = dataStart + compSize;
    } else {
      offset++;
    }
  }
  return null;
}

const xml = findLocalFile(buf, 'word/document.xml');
if (!xml) { console.log('Could not find document.xml'); process.exit(1); }

// Extract text, preserving paragraph breaks
const paragraphs = xml.split(/<w:p[ >]/);
const lines = paragraphs.map(p => {
  const texts = p.match(/(?<=<w:t[^>]*>)[^<]+/g) || [];
  return texts.join('');
}).filter(l => l.length > 0);
console.log(lines.join('\n'));
"
